 const moneyFormat=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
 function storyExtra(r){
  if(r.slug!=='csac-2027')return '';
  const d=csacEvidence, ordered=Object.entries(d.totals).sort((a,b)=>b[1]-a[1]);
  const table=(head,rows)=>'<div class="qp-story-table"><table><thead><tr>'+head.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
  return '<section class="qp-story-data"><h3>Who requested funding?</h3><p>Requests by service category, calculated from all 46 published applications. Source: September 1 City notice, rechecked November 14. No figure below is a grant award.</p><div class="qp-story-bars">'+ordered.map(([k,v])=>'<div class="qp-story-bar"><div><strong>'+esc(k)+'</strong><span>'+esc(moneyFormat(v))+'</span></div><meter min="0" max="'+ordered[0][1]+'" value="'+v+'" aria-label="'+esc(k+' '+moneyFormat(v))+'">'+v+'</meter></div>').join('')+'</div><details class="qp-report-popout"><summary>All 46 applicants and amounts requested</summary>'+table(['Organization','Published category','Requested'],d.rows.map(([n,v,k])=>[n,k,moneyFormat(v)]))+'<p><strong>Total: '+moneyFormat(d.total)+'</strong></p></details><p><a href="'+esc(d.url)+'">Original September 1 application list</a> · <a href="'+esc(d.statementUrl)+'">November 3 City statement</a> · <a href="'+esc(d.countyNoticeUrl)+'">County sponsorship pause notice (separate program)</a></p></section>';
 }
 function story(r){
  return publicStories[r.slug]||[['What the records show',r.summary],['What it means',r.qification.assessment]];
 }
 function renderStory(r){
  return '<section class="qp-story" aria-label="The story"><p class="qp-story-lead">'+esc(r.summary)+'</p>'+story(r).map(([h,p])=>'<section><h3>'+esc(h)+'</h3><p>'+esc(p)+'</p></section>').join('')+storyExtra(r)+'<p class="qp-story-source"><a href="#original-sources">Original records and evidence dates</a></p></section>';
 }

 function render40(r){
  const rows=coverage40(r);
  return '<details open class="qp40 qp-report-popout" id="coverage-40"><summary>40 research perspectives — select a finding to expand</summary><p>Findings and limitations from this dated study; not every perspective has enough evidence for a conclusion.</p>'+groups40.map(([g])=>'<section class="qp40-group"><h3>'+esc(g)+'</h3><ol start="'+rows.find(x=>x.group===g).n+'">'+rows.filter(x=>x.group===g).map(x=>'<li class="qp40-row" data-coverage="'+x.n+'"><details><summary><span class="qp40-title">'+esc(x.title)+'</span><span class="qp40-finding">'+esc(x.answer)+'</span></summary><div class="qp40-depth"><p class="qp-coverage-note">'+esc(x.classification==='Not assessed'?'Not yet established':'Dated evidence and interpretation')+'</p>'+(x.detail.length?'<h4>Related evidence and context</h4>'+list([...new Set(x.detail.filter(v=>v&&v!==x.answer))]):'<p>This point has not been established by the reviewed records.</p>')+'<a href="#original-sources">Original report sources and notes</a></div></details></li>').join('')+'</ol></section>').join('')+'</details><section class="qp40-summary"><h3>Summary</h3><p><strong>The answer:</strong> '+esc(r.summary)+'</p><p><strong>What it means:</strong> '+esc(r.qification.assessment)+'</p><p><strong>Practical takeaway:</strong> '+esc((r.readerNotes||readerNotes[r.slug])?.[35]||r.actions[0])+'</p></section>';
 }
 function researchPrompt(question,audience='resident',format='full report'){
  return ['Research this Pueblo-region question: '+String(question).trim(),'Audience: '+audience+'; output: '+format+'.','Give the actual supported answer first. Find controlling public primary sources, relevant historical records and contrary evidence. Distinguish dates, jurisdiction, authority, financial stages, facts, claims, interpretations and unknowns. Never invent sources or outcomes.','Apply applicable Q methods: historical recovery, GLEAN, DBL, micro-to-macro connections, child and community impact, EE/EH/T2Y where measurable, RX/LEAP alternatives and SHOCK scenarios. State calculations and assumptions.','Deliver information and actionable resources, not research chores. Provide a short visible finding plus deeper explanation, evidence and technical detail for these 40 sections:',...groups40.map(([g,t])=>g+': '+t.join('; ')),'Finish with synthesis, practical resources, original sources with dates, corrections and limitations. Mark unassessed or inapplicable sections honestly. Do not claim external actions or verification that did not take place.'].join('\n\n');
 }

