 'water-budget-evidence':[['Compare resource scenarios','twin.html']],
 'records-request':[['Inspect the open documentary contradiction','evidence-desk.html#challenge']],
 'pueblo-flood-history':[['Explore historical Pueblo resources','learn-pueblo.html']],
